function initializeTetrisWorld(){const layer=$("#tetrisPieces");if(!layer)return;const shapes={I:[[0,0],[1,0],[2,0],[3,0]],O:[[0,0],[1,0],[0,1],[1,1]],T:[[0,0],[1,0],[2,0],[1,1]],S:[[1,0],[2,0],[0,1],[1,1]],Z:[[0,0],[1,0],[1,1],[2,1]],J:[[0,0],[0,1],[1,1],[2,1]],L:[[2,0],[0,1],[1,1],[2,1]]},names=Object.keys(shapes),colors=["cyan","violet","pink","amber","lime","blue","coral"];for(let index=0;index<7;index++){const piece=document.createElement("div");piece.className=`tetromino tone-${colors[index]}`;piece.style.setProperty("--x",`${8+index*14}vw`);piece.style.setProperty("--size",`${13+(index%3)*3}px`);piece.style.setProperty("--fall",`${19+(index%4)*3}s`);piece.style.setProperty("--delay",`${-(index*4.2)}s`);for(const [x,y] of shapes[names[index]]){const block=document.createElement("i");block.style.setProperty("--bx",x);block.style.setProperty("--by",y);piece.append(block)}layer.append(piece)}}
