function renderAttachmentTray(){const tray=$("#attachmentTray");tray.innerHTML=state.pendingAttachments.map((item,index)=>`<div class="attachment ${item.kind}">${item.kind==="image"?`<img src="${escapeHtml(item.url)}" alt="${escapeHtml(item.name)}">`:`<span class="document-icon">PDF</span><small>${escapeHtml(item.name)}</small>`}<button data-remove-attachment="${index}" aria-label="Remove ${escapeHtml(item.name)}">×</button></div>`).join("");tray.classList.toggle("visible",state.pendingAttachments.length>0);tray.querySelectorAll("[data-remove-attachment]").forEach(button=>button.addEventListener("click",()=>{state.pendingAttachments.splice(Number(button.dataset.removeAttachment),1);renderAttachmentTray()}));}
function readAttachment(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({kind:file.type.startsWith("image/")?"image":"document",name:file.name,url:reader.result,size:file.size,mimeType:file.type||({pdf:"application/pdf",txt:"text/plain",md:"text/markdown",csv:"text/csv"}[file.name.split(".").pop().toLowerCase()]||"")});reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)});}
$("#attachButton").addEventListener("click",()=>$("#attachmentInput").click());$("#attachmentInput").addEventListener("change",async event=>{const files=[...event.target.files];event.target.value="";for(const file of files){const isImage=file.type.startsWith("image/"),documentCount=state.pendingAttachments.filter(item=>item.kind==="document").length,imageCount=state.pendingAttachments.filter(item=>item.kind==="image").length;if((isImage&&imageCount>=4)||(!isImage&&documentCount>=2)){showToast(`Attachment limit reached for ${isImage?"images":"documents"}`,"warning");continue}const limit=isImage?4_000_000:file.type==="application/pdf"?8_000_000:2_000_000;if(file.size>limit){showToast(`${file.name} exceeds the ${limit/1_000_000} MB limit`,"warning");continue}try{state.pendingAttachments.push(await readAttachment(file))}catch{showToast(`Could not read ${file.name}`,"error")}}renderAttachmentTray();});
