const concurrencyState={active:false,running:false,batchStarted:0,batchFinished:0,wallTimer:null,workers:Array.from({length:4},(_,index)=>({index,status:"idle",controller:null,started:0,firstToken:0,finished:0,content:"",reasoning:"",usage:{},error:""}))};
const concurrencyEls={workspace:$("#concurrencyWorkspace"),workers:$("#concurrencyWorkers"),prompt:$("#concurrencyPrompt"),run:$("#concurrencyRun"),stopAll:$("#concurrencyStopAll"),chatMode:$("#chatModeButton"),concurrencyMode:$("#concurrencyModeButton"),completed:$("#concurrencyCompleted"),wall:$("#concurrencyWall"),meanTtft:$("#concurrencyMeanTtft"),p95Ttft:$("#concurrencyP95Ttft"),aggregateTps:$("#concurrencyAggregateTps"),tokens:$("#concurrencyTokens")};

function workerCard(worker){return `<article class="worker-card" data-worker="${worker.index}"><header class="worker-head"><div class="worker-title"><i></i><strong>Worker ${worker.index+1}</strong><span class="worker-status">Idle</span></div><button class="worker-stop" data-stop-worker="${worker.index}" disabled aria-label="Stop worker ${worker.index+1}" title="Stop this worker">■</button></header><div class="worker-output"><div class="worker-placeholder">The streamed response will appear here.</div></div><footer class="worker-metrics"><div data-metric="ttft"><small>TTFT</small><b data-worker-ttft>—</b></div><div data-metric="tps"><small>Output</small><b data-worker-tps>—</b></div><div data-metric="total"><small>Total</small><b data-worker-total>—</b></div><div data-metric="tokens"><small>Tokens</small><b data-worker-tokens>—</b></div></footer></article>`}
function renderConcurrencyWorkers(){concurrencyEls.workers.innerHTML=concurrencyState.workers.map(workerCard).join("");concurrencyEls.workers.querySelectorAll("[data-stop-worker]").forEach(button=>button.addEventListener("click",()=>stopConcurrencyWorker(Number(button.dataset.stopWorker))));}
function getWorkerNode(index){return concurrencyEls.workers.querySelector(`[data-worker="${index}"]`)}
function resetConcurrencyWorker(worker){worker.status="queued";worker.controller=null;worker.started=0;worker.firstToken=0;worker.finished=0;worker.content="";worker.reasoning="";worker.usage={};worker.error="";const card=getWorkerNode(worker.index);card.className="worker-card";card.querySelector(".worker-status").className="worker-status";card.querySelector(".worker-status").textContent="Queued";card.querySelector(".worker-output").innerHTML='<div class="worker-placeholder">Queued for parallel dispatch…</div>';card.querySelectorAll(".worker-metrics b").forEach(value=>value.textContent="—");card.querySelectorAll(".best-metric").forEach(value=>value.classList.remove("best-metric"));card.querySelector(".worker-stop").disabled=false;}
function setWorkerStatus(worker,status,label=status){worker.status=status;const node=getWorkerNode(worker.index),badge=node.querySelector(".worker-status");badge.className=`worker-status ${status}`;badge.textContent=label;node.classList.toggle("worker-failed",status==="failed");node.classList.toggle("worker-cancelled",status==="cancelled");node.querySelector(".worker-stop").disabled=!["gateway","waiting","streaming"].includes(status);}
function updateWorkerMetrics(worker){const card=getWorkerNode(worker.index),ttft=worker.firstToken?worker.firstToken-worker.started:null,total=worker.finished?worker.finished-worker.started:null,completion=Number(worker.usage.completion_tokens||0),generation=ttft!=null&&total!=null?Math.max(1,total-ttft):null,tps=completion&&generation?completion/(generation/1000):null;card.querySelector("[data-worker-ttft]").textContent=ttft==null?"—":formatSeconds(ttft);card.querySelector("[data-worker-tps]").textContent=tps==null?"—":`${tps.toFixed(1)} tok/s`;card.querySelector("[data-worker-total]").textContent=total==null?"—":formatSeconds(total);card.querySelector("[data-worker-tokens]").textContent=completion?`${completion} out · ${worker.usage.prompt_tokens||0} in`:worker.status==="failed"?"Failed":"—";}
function percentile95(values){if(!values.length)return null;const sorted=[...values].sort((a,b)=>a-b);return sorted[Math.max(0,Math.ceil(sorted.length*.95)-1)];}
function workerDecodeTps(worker){return decodeTokensPerSecond(worker);}
function highlightConcurrencyWinners(successful,settled){document.querySelectorAll(".best-metric").forEach(cell=>{cell.classList.remove("best-metric");cell.querySelector(".best-badge")?.remove()});if(settled.length!==4||!successful.length)return;const winners=selectConcurrencyWinners(successful);for(const [index,metric] of [[winners.ttftIndex,"ttft"],[winners.tpsIndex,"tps"]]){if(index==null)continue;const cell=getWorkerNode(index).querySelector(`[data-metric="${metric}"]`);cell.classList.add("best-metric");cell.insertAdjacentHTML("beforeend",'<span class="best-badge">Best</span>')}}
function updateConcurrencySummary(){const settled=concurrencyState.workers.filter(worker=>["completed","failed","cancelled"].includes(worker.status)),successful=concurrencyState.workers.filter(worker=>worker.status==="completed"),failed=concurrencyState.workers.filter(worker=>worker.status==="failed").length,ttfts=successful.filter(worker=>worker.firstToken).map(worker=>worker.firstToken-worker.started),completionTokens=successful.reduce((sum,worker)=>sum+Number(worker.usage.completion_tokens||0),0),end=concurrencyState.batchFinished||performance.now(),wall=concurrencyState.batchStarted?Math.max(0,end-concurrencyState.batchStarted):0,mean=ttfts.length?ttfts.reduce((sum,value)=>sum+value,0)/ttfts.length:null,p95=percentile95(ttfts);concurrencyEls.completed.textContent=`${successful.length} / 4`;concurrencyEls.wall.textContent=wall?formatSeconds(wall):"—";concurrencyEls.meanTtft.textContent=mean==null?"—":formatSeconds(mean);concurrencyEls.p95Ttft.textContent=p95==null?"—":formatSeconds(p95);concurrencyEls.aggregateTps.textContent=completionTokens&&wall?`${(completionTokens/(wall/1000)).toFixed(1)} tok/s`:"—";concurrencyEls.tokens.textContent=settled.length?`${completionTokens.toLocaleString()} / ${failed} failed`:"—";highlightConcurrencyWinners(successful,settled);}
function renderWorkerStream(worker){const output=getWorkerNode(worker.index).querySelector(".worker-output"),wasFollowing=output.scrollHeight-output.clientHeight-output.scrollTop<70;output.innerHTML=`<div class="message-body cursor" dir="auto">${worker.reasoning?`<div class="thinking-block">${markdown(worker.reasoning)}</div>`:""}${markdown(worker.content)}</div>`;enhanceRendered(output);if(wasFollowing)output.scrollTop=output.scrollHeight;}

async function runConcurrencyWorker(worker,prompt,settings){
  const controller=new AbortController();worker.controller=controller;worker.started=performance.now();setWorkerStatus(worker,"gateway","Gateway wait");
  const output=getWorkerNode(worker.index).querySelector(".worker-output");output.innerHTML=`<div class="worker-placeholder">Worker ${worker.index+1} is waiting for the inference gateway…</div>`;
  try{
    const response=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},signal:controller.signal,body:JSON.stringify({request_kind:"concurrency",history_enabled:false,messages:[{role:"user",content:prompt}],max_tokens:settings.maxTokens,temperature:settings.temperature,enable_thinking:settings.reasoning,web_search:false})});
    if(!response.ok){const detail=await response.json().catch(()=>({}));throw new Error(detail.error||`Request failed (${response.status})`)}
    setWorkerStatus(worker,"waiting","First-token wait");output.innerHTML=`<div class="worker-placeholder">Worker ${worker.index+1} is connected and waiting for its first token…</div>`;
    const reader=response.body.getReader(),decoder=new TextDecoder();let buffer="";
    while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split("\n");buffer=lines.pop()||"";for(const line of lines){if(!line.startsWith("data: "))continue;const data=line.slice(6).trim();if(!data||data==="[DONE]")continue;const chunk=JSON.parse(data);if(chunk.usage)worker.usage=chunk.usage;for(const choice of chunk.choices||[]){const delta=choice.delta||{},next=delta.content||"",thought=delta.reasoning||delta.reasoning_content||"";if((next||thought)&&!worker.firstToken){worker.firstToken=performance.now();setWorkerStatus(worker,"streaming","Streaming")}worker.content+=next;worker.reasoning+=thought;}if(worker.content||worker.reasoning)renderWorkerStream(worker);}}
    if(!worker.firstToken)throw new Error("The stream ended without generated text");worker.finished=performance.now();setWorkerStatus(worker,"completed","Completed");output.querySelector(".message-body")?.classList.remove("cursor");output.scrollTop=output.scrollHeight;
  }catch(error){worker.finished=performance.now();if(error.name==="AbortError"){setWorkerStatus(worker,"cancelled","Cancelled");if(!worker.content&&!worker.reasoning)output.innerHTML='<div class="worker-placeholder">Request cancelled.</div>'}else{worker.error=error.message;setWorkerStatus(worker,"failed","Failed");output.innerHTML=`<div class="worker-placeholder"><strong>Request failed</strong><br>${escapeHtml(error.message)}</div>`}}
  finally{output.querySelector(".message-body")?.classList.remove("cursor");worker.controller=null;updateWorkerMetrics(worker);updateConcurrencySummary();announce(`Worker ${worker.index+1} ${worker.status}.`)}
}

function setConcurrencyControlsDisabled(disabled){concurrencyEls.prompt.disabled=disabled;for(const id of ["concurrencyMaxTokens","concurrencyTemperature","concurrencyReasoning"])$("#"+id).disabled=disabled;document.querySelectorAll("[data-concurrency-prompt]").forEach(button=>button.disabled=disabled);}
async function runConcurrency(){const prompt=concurrencyEls.prompt.value.trim();if(concurrencyState.running||!prompt){concurrencyEls.prompt.focus();return}const settings={maxTokens:Number($("#concurrencyMaxTokens").value),temperature:Number($("#concurrencyTemperature").value),reasoning:$("#concurrencyReasoning").checked};concurrencyState.running=true;concurrencyState.batchStarted=performance.now();concurrencyState.batchFinished=0;concurrencyState.workers.forEach(resetConcurrencyWorker);concurrencyEls.run.disabled=true;concurrencyEls.stopAll.disabled=false;setConcurrencyControlsDisabled(true);setEndpointState("busy","Busy · 4 requests");announce("Four concurrent inference requests started.");updateConcurrencySummary();concurrencyState.wallTimer=setInterval(updateConcurrencySummary,100);await Promise.allSettled(concurrencyState.workers.map(worker=>runConcurrencyWorker(worker,prompt,settings)));concurrencyState.batchFinished=performance.now();clearInterval(concurrencyState.wallTimer);concurrencyState.wallTimer=null;concurrencyState.running=false;concurrencyEls.run.disabled=false;concurrencyEls.stopAll.disabled=true;setConcurrencyControlsDisabled(false);updateConcurrencySummary();setEndpointState(concurrencyState.workers.some(worker=>worker.status==="completed")?"ready":"unavailable");announce(`Concurrency run finished. ${concurrencyState.workers.filter(worker=>worker.status==="completed").length} of 4 workers completed.`);}
function stopConcurrencyWorker(index){const worker=concurrencyState.workers[index];worker?.controller?.abort();}
function stopAllConcurrency(){concurrencyState.workers.forEach(worker=>worker.controller?.abort());}
async function setWorkspaceMode(mode){const enableConcurrency=mode==="concurrency";if(enableConcurrency===concurrencyState.active)return;if(state.busy&&!await customConfirm("Stop the current chat response and open Concurrency 4?",{title:"Switch workspace?",confirmLabel:"Stop and switch"}))return;if(concurrencyState.running&&!await customConfirm("Stop all four requests and return to Chat?",{title:"Leave Concurrency 4?",confirmLabel:"Stop all and switch"}))return;if(state.busy)stopGeneration();if(concurrencyState.running)stopAllConcurrency();concurrencyState.active=enableConcurrency;document.body.classList.toggle("concurrency-mode",enableConcurrency);concurrencyEls.workspace.hidden=!enableConcurrency;concurrencyEls.chatMode.classList.toggle("active",!enableConcurrency);concurrencyEls.concurrencyMode.classList.toggle("active",enableConcurrency);concurrencyEls.chatMode.setAttribute("aria-pressed",String(!enableConcurrency));concurrencyEls.concurrencyMode.setAttribute("aria-pressed",String(enableConcurrency));if(enableConcurrency)concurrencyEls.prompt.focus();else els.prompt.focus();}

