document.querySelectorAll("[data-concurrency-prompt]").forEach(button=>button.addEventListener("click",()=>{concurrencyEls.prompt.value=button.dataset.concurrencyPrompt;concurrencyEls.prompt.focus()}));
function scrollToWorker(index){const cards=[...concurrencyEls.workers.querySelectorAll(".worker-card")],target=cards[Math.max(0,Math.min(cards.length-1,index))];target?.scrollIntoView({behavior:"smooth",block:"nearest",inline:"center"});$("#workerPosition").textContent=`Worker ${Math.max(0,Math.min(cards.length-1,index))+1} of 4`;}
$("#workerPrevious").addEventListener("click",()=>{const current=Math.round(concurrencyEls.workers.scrollLeft/Math.max(1,concurrencyEls.workers.clientWidth));scrollToWorker(current-1)});$("#workerNext").addEventListener("click",()=>{const current=Math.round(concurrencyEls.workers.scrollLeft/Math.max(1,concurrencyEls.workers.clientWidth));scrollToWorker(current+1)});concurrencyEls.workers.addEventListener("scroll",()=>{const cards=[...concurrencyEls.workers.querySelectorAll(".worker-card")],center=concurrencyEls.workers.scrollLeft+concurrencyEls.workers.clientWidth/2,index=cards.reduce((best,card,i)=>Math.abs(card.offsetLeft+card.offsetWidth/2-center)<Math.abs(cards[best].offsetLeft+cards[best].offsetWidth/2-center)?i:best,0);$("#workerPosition").textContent=`Worker ${index+1} of 4`},{passive:true});
for(const id of ["concurrencyMaxTokens","concurrencyTemperature"]){const input=$("#"+id),output=$("#"+id+"Value");input.addEventListener("input",()=>output.textContent=input.value)}
